import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.N3ArWwc6.js";const r="/owl-sda/webui/dashboard-trends.png",i="/owl-sda/webui/dashboard-output.png",b=JSON.parse('{"title":"Web UI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/web-ui.md","filePath":"guide/web-ui.md"}'),d={name:"guide/web-ui.md"};function n(h,e,l,c,p,u){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="web-ui" tabindex="-1">Web UI <a class="header-anchor" href="#web-ui" aria-label="Permalink to &quot;Web UI&quot;">​</a></h1><p>OWL-SDA ships with an opt-in local dashboard that shows a run as it happens: the stage timeline, every agent&#39;s messages and tool calls, the shared triple store, the output file, and trend charts for triples, violations, and shapes over time.</p><p>The dashboard is read-only. It renders the benchmark output directory from disk, so it never interferes with the run.</p><h2 id="starting-it" tabindex="-1">Starting it <a class="header-anchor" href="#starting-it" aria-label="Permalink to &quot;Starting it&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> target/owlsda.jar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --config</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/project-1/config.yml</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --web-ui</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Option</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>--web-ui</code></td><td>off</td><td>Starts the dashboard on <code>http://localhost:8080</code>.</td></tr><tr><td><code>--web-ui-port</code></td><td><code>8080</code></td><td>Port to listen on.</td></tr></tbody></table><p>The dashboard reads the benchmark output, so <strong><code>benchmark.enabled: true</code> must be set in your config</strong> — without it the page shows a &quot;Waiting for benchmark data…&quot; placeholder and OWL-SDA logs a warning at startup. See <a href="./configuration">Configuration</a> for <code>benchmark.enabled</code>, <code>benchmark.output-dir</code>, and <code>benchmark.live-interval-seconds</code>.</p><p>The server keeps serving after the run finishes:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Run finished. Web UI still available at http://localhost:8080 -- press Ctrl+C to exit.</span></span></code></pre></div><p>Press <code>Ctrl+C</code> when you are done inspecting the results.</p><p>The page polls every 2.5 seconds. How often the underlying data changes is set by <code>benchmark.live-interval-seconds</code> (default 15), which controls how often a <code>LIVE</code> snapshot is flushed while a round is still running.</p><h2 id="the-dashboard" tabindex="-1">The dashboard <a class="header-anchor" href="#the-dashboard" aria-label="Permalink to &quot;The dashboard&quot;">​</a></h2><p><img src="'+r+'" alt="OWL-SDA run dashboard showing the stat row, tab bar, and the Trends charts"></p><h3 id="header-and-stat-row" tabindex="-1">Header and stat row <a class="header-anchor" href="#header-and-stat-row" aria-label="Permalink to &quot;Header and stat row&quot;">​</a></h3><p>The header carries the current stage badge (<code>LIVE</code>, <code>GENERATE</code>, <code>FINALIZING</code>, <code>REVIEW_ITERATION_&lt;n&gt;</code>, <code>REVIEW_ACCEPTED</code>, <code>REVIEW_REJECTED</code>), a running/idle indicator, a server connection dot, and the last refresh time. A run counts as &quot;running&quot; when the newest snapshot is younger than three live intervals (at least 30 seconds).</p><p>Five stat cards sit above the tabs: <strong>Shapes Processed</strong>, <strong>Violations</strong>, <strong>Triples</strong>, <strong>Duration</strong>, and <strong>Total Tokens</strong> (with an input/output split underneath). Duration is measured from the first snapshot of the run, not from the current stage.</p><p>The <strong>Violations</strong> card is clickable — it opens a modal with the full SHACL validation report, backed by <code>/api/violations</code>. Press <code>Escape</code> or click outside to close it.</p><h3 id="stages-sidebar" tabindex="-1">Stages sidebar <a class="header-anchor" href="#stages-sidebar" aria-label="Permalink to &quot;Stages sidebar&quot;">​</a></h3><p>Every snapshot in <code>benchmark-summary.json</code> appears as a row with its shape count, violation count, and duration, newest first. Consecutive <code>LIVE</code> ticks are collapsed into a single row with a multiplier, so only real milestones plus one &quot;still working&quot; entry are shown.</p><h3 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tab</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Messages</strong></td><td>One sub-tab per session role (<code>supervisor</code>, <code>reviewer</code>, <code>worker_0</code>, <code>worker_1</code>, …). Shows that role&#39;s full transcript with tool calls and their results merged into single cards, Turtle syntax highlighting, collapsible long bodies, and an auto-scroll toggle. Above the transcript, the role&#39;s current named contexts (&quot;Delegation Instructions&quot;, &quot;Validation Report&quot;, &quot;Ontology Summary&quot;, …) are shown as collapsible panels.</td></tr><tr><td><strong>Output</strong></td><td>The current contents of the file at <code>output-path</code>, with size and Turtle highlighting.</td></tr><tr><td><strong>Triple Store</strong></td><td>The shared <code>WorkerTripleStore</code> dump (<code>triplestore.ttl</code>) from the latest snapshot.</td></tr><tr><td><strong>Trends</strong></td><td>Three line charts over the run&#39;s elapsed time: <strong>Triples in store</strong>, <strong>SHACL violations</strong>, and <strong>Shapes processed</strong>. Hovering shows a crosshair and a tooltip with the value and how far into the run it was. Unmeasured points (for example violations before the first validation) break the line rather than being plotted as zero.</td></tr></tbody></table><p><img src="'+i+`" alt="The Output tab rendering the generated Turtle with syntax highlighting"></p><h3 id="live-per-role-indicators" tabindex="-1">Live per-role indicators <a class="header-anchor" href="#live-per-role-indicators" aria-label="Permalink to &quot;Live per-role indicators&quot;">​</a></h3><p>Each role sub-tab in the Messages tab carries three live figures:</p><ul><li>A <strong>busy dot</strong> — whether that session is currently mid-prompt.</li><li>The <strong>model name</strong>, with the provider in its tooltip.</li><li>A <strong>context usage percentage</strong>, shown only when a context window is configured.</li></ul><p>These come from <code>metadata.txt</code>, which <code>SnapshotWriter</code> refreshes on every snapshot:</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>model.&lt;role&gt;</code></td><td>Configured model for the role.</td></tr><tr><td><code>provider.&lt;role&gt;</code></td><td>Effective provider, falling back to <code>client.provider</code> when the role sets none.</td></tr><tr><td><code>busy.&lt;role&gt;</code></td><td>Whether the session is currently waiting on the model.</td></tr><tr><td><code>context.&lt;role&gt;.used</code></td><td>Prompt tokens on the <strong>last</strong> completed call — not a cumulative total.</td></tr><tr><td><code>context.&lt;role&gt;.limit</code></td><td>The role&#39;s <code>context-window-tokens</code>. Zero means unset, and the gauge is hidden.</td></tr></tbody></table><p><code>&lt;role&gt;</code> is <code>supervisor</code>, <code>reviewer</code>, or <code>worker.worker_N</code>. Model and provider are written once per role rather than per worker index, since all pool workers share one configured model. Set <code>client.&lt;role&gt;.context-window-tokens</code> in the config to get a usage gauge at all.</p><h2 id="http-api" tabindex="-1">HTTP API <a class="header-anchor" href="#http-api" aria-label="Permalink to &quot;HTTP API&quot;">​</a></h2><p>The dashboard is a static page over a small JSON API served by <code>WebUiServer</code>. All endpoints are <code>GET</code>, take no authentication, and are stable enough to script against.</p><table tabindex="0"><thead><tr><th>Route</th><th>Returns</th></tr></thead><tbody><tr><td><code>/</code></td><td>The dashboard itself (<code>index.html</code>, <code>app.js</code>, <code>style.css</code> — a fixed allowlist, no filesystem traversal).</td></tr><tr><td><code>/api/state</code></td><td><code>{ benchmarkEnabled, benchmarkDirExists, liveIntervalSeconds, metadata, roles }</code>. <code>metadata</code> is <code>metadata.txt</code> as a flat object; <code>roles</code> lists the session roles that have a message log, ordered supervisor, reviewer, then <code>worker_0</code>…</td></tr><tr><td><code>/api/history</code></td><td>The raw <code>benchmark-summary.json</code> array — one entry per snapshot, with <code>stage</code>, <code>timestamp</code>, <code>shapesProcessed</code>, <code>currentViolations</code>, <code>triplestoreSize</code>, <code>durationMs</code>, and token counts. <code>[]</code> before the first snapshot.</td></tr><tr><td><code>/api/messages?role=&lt;role&gt;</code></td><td>That role&#39;s message log. <code>TOOL_INVOCATION</code> entries are enriched with a parsed <code>tool: { name, arguments, argumentsAreJson }</code>. <code>404</code> with <code>{&quot;error&quot;:&quot;unknown role&quot;}</code> for an unknown role.</td></tr><tr><td><code>/api/contexts?role=&lt;role&gt;</code></td><td><code>[{ name, content }]</code> for the role&#39;s current named contexts. Files from earlier rounds (prefixed <code>round_N-</code>) are excluded, so this is the round in progress only.</td></tr><tr><td><code>/api/triplestore</code></td><td><code>triplestore.ttl</code> as <code>{ path, exists, sizeBytes, truncated, content }</code>.</td></tr><tr><td><code>/api/output</code></td><td>The file at <code>output-path</code>, same shape as above.</td></tr><tr><td><code>/api/violations</code></td><td>The most recent <code>Validation Report.txt</code> held by any role (supervisor and reviewer are checked first), same shape as above.</td></tr></tbody></table><p>The three file endpoints truncate content at 2,000,000 characters and set <code>truncated: true</code> when they do.</p><p>Example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/state</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.metadata.stage, .roles&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/history</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.[-1]&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/messages?role=worker_0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;[.[] | select(.tool) | .tool.name]&#39;</span></span></code></pre></div><h2 id="where-the-data-comes-from" tabindex="-1">Where the data comes from <a class="header-anchor" href="#where-the-data-comes-from" aria-label="Permalink to &quot;Where the data comes from&quot;">​</a></h2><p>Everything the dashboard shows is read from <code>&lt;benchmark.output-dir&gt;/live/</code> — the same directory <code>BenchmarkService</code> overwrites in place as the run progresses. Nothing is cached in the server, so restarting the dashboard against a finished run&#39;s directory replays it exactly.</p><p>See <a href="./benchmarking">Benchmarking</a> for the full snapshot layout, the archived runs under <code>archive/&lt;timestamp&gt;/</code>, and the offline plotting script.</p>`,37)])])}const k=t(d,[["render",n]]);export{b as __pageData,k as default};
